def solve(g):
    from collections import Counter
    hh,ww=len(g),len(g[0])
    bgc=Counter(x for r in g for x in r).most_common(1)[0][0]
    # find template: contiguous line of non-bg length>1
    tpl=None; orient=None; pos=None
    for r in range(hh):
        cells=[(r,j) for j in range(ww) if g[r][j]!=bgc]
        # contiguous runs
        run=[]
        for j in range(ww+1):
            if j<ww and g[r][j]!=bgc: run.append((r,j))
            else:
                if len(run)>1: tpl=[g[r][jj] for (rr,jj) in run]; orient='H'; pos=(run[0][0],run[0][1])
                run=[]
    for c in range(ww):
        run=[]
        for i in range(hh+1):
            if i<hh and g[i][c]!=bgc: run.append((i,c))
            else:
                if len(run)>1: tpl=[g[i][cc] for (ii,cc) in run]; orient='V'; pos=(run[0][0],run[0][1])
                run=[]
    L=len(tpl); half=L//2
    out=[row[:] for row in g]
    marks=[(i,j) for i in range(hh) for j in range(ww) if g[i][j]!=bgc and (i,j)!=pos and (j not in range(pos[1],pos[1]+L) if orient=='H' else i not in range(pos[0],pos[0]+L))]
    for (i,j) in marks:
        for k,v in enumerate(tpl):
            if orient=='H':
                jj=j-half+k
                if 0<=jj<ww: out[i][jj]=v
            else:
                ii=i-half+k
                if 0<=ii<hh: out[ii][j]=v
    return out
